SourceCode.Declaration:
/// <summary>
/// CB233_TOReceiptDetails custom service
/// Entry points
/// - receiveMulti
/// - receiveSingle
/// </summary>
class METInventTransferOrderService
{
}

Method.Source:
    /// <summary>
    /// Service endpoint to receive multiple TO receipt
    /// </summary>
    /// <param name = "request">Service request</param>
    /// <returns>Returns an array of multiple reponses</returns>
    public METBaseMultiResponseContract receiveMulti(METInventTransferOrderReceiveRequestMultiContract request)
    {
        List                            responseList;
        METBaseMultiResponseContract    responseContract = new METBaseMultiResponseContract();

        responseList = this.processReceiveMulti(request);
        
        responseContract.parmResponses(responseList);

        return responseContract;
    }

    /// <summary>
    /// Process multiple TO receipts
    /// </summary>
    /// <param name = "_request">Service request</param>
    /// <returns>Returns a list of multiple reponses</returns>
    private List processReceiveMulti(METInventTransferOrderReceiveRequestMultiContract _request)
    {
        METInventTransferOrderReceiveRequestSingleContract  receiptContract;
        
        List                    ret = new List(Types::Class);
        METBaseResponseContract receiptResponse;
        Description255          message;
        
        List receipts = _request.parmReceipts();
        
        if (receipts)
        {
            // validate number of receipts does not exceed parameters
            message = this.validateReceipts(receipts.elements());            
            
            if (!message)
            {
                ListIterator receiptsLi = new ListIterator(receipts);

                // Loop through all receipts in the request
                while (receiptsLi.more())
                {
                    receiptContract = receiptsLi.value();

                    // Process receipt by reusing the receiveSingle (service endpoint)
                    receiptResponse = this.receiveSingle(receiptContract);

                    // Add receipt response in the list
                    ret.addEnd(receiptResponse);

                    // Next receipt
                    receiptsLi.next();
                }
            }
            else
            {
                // Exceed max number of TO receipts
                receiptResponse = METBaseResponseContract::newFromParameters(METConstants::emptyString, METProcessingStatus::Error, message);

                // Add receipt response in the list
                ret.addEnd(receiptResponse);
            }
        }
        else
        {
            // No receipts in the request
            receiptResponse = METBaseResponseContract::newFromParameters(METConstants::emptyString, METProcessingStatus::Error, "@MET:ReceiptsValidation");

            // Add receipt response in the list
            ret.addEnd(receiptResponse);
        }

        return ret;
    }

    /// <summary>
    /// Receive single TO receipt
    /// </summary>
    /// <param name = "request">Single TO receipt request contract</param>
    /// <returns>Base response contract</returns>
    public METBaseResponseContract receiveSingle(METInventTransferOrderReceiveRequestSingleContract request)
    {
        #OCCRetryCount
        METProcessingStatus                         result;
        Description255                              message;

        InventTransferParmTable inventTransferParmTable;    
        InventTransferParmLine  inventTransferParmLineUpdatedTmp;        
        METInventTransferOrderReceiveHeaderContract headerContract = request.parmHeaderContract();
        InventTransferId inventTransferId = headerContract.parmInventTransferId();
        DataAreaId dataAreaId = headerContract.parmDataAreaId();

        System.Exception ex;

        try
        {
            ttsbegin;
            
            // only validate dataAreaId
            message = this.validateHeaderDataAreaId(headerContract);

            if (!message)
            {
                changecompany(dataAreaId)
                {
                    // Validate header after change company to make sure we can retrive the TO in the right company
                    message = this.validateHeader(headerContract);
                    
                    if (!message)
                    {
                        // Create InventTransferParmTable
                        inventTransferParmTable = this.createInventTransferParmTable(headerContract, InventTransferUpdateType::Receive);

                        // Create InventTransferParmLines from the shipment
                        this.createInventTransferParmLine(inventTransferParmTable);

                        // Update receive qty and CW receive now
                        message = this.processLinesContract(request.parmLinesContract(), inventTransferParmTable.ParmId, inventTransferId, inventTransferParmLineUpdatedTmp);

                        if (!message)
                        {
                            // Trigger inventTransferMultiReceive.runUpdate
                            this.postTOReceipt(inventTransferParmTable, inventTransferParmLineUpdatedTmp);
                        
                        }
                        else
                        {
                            result = METProcessingStatus::Error;
                        }
                    }
                    else
                    {
                        result = METProcessingStatus::Error;
                    }
                }
            }
            else
            {
                result = METProcessingStatus::Error;
            }

            ttscommit;

            if (!message)
            {
                result = METProcessingStatus::Success;
                message = "@MET:ReceiptSuccessful";
            }
        }        
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    message = "@MET:ReceiptDeadlock";
                    result = METProcessingStatus::Error;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                message = "@MET:ReceiptDeadlock";
                result = METProcessingStatus::Error;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    message = "@MET:ReceiptUpdateConflict";
                    result = METProcessingStatus::Error;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                message = "@MET:ReceiptUpdateConflict";
                result = METProcessingStatus::Error;
            }
        }
        catch(ex)
        {
            message = strFmt("@MET:ReceiptFailed", ex.ToString());
            result = METProcessingStatus::Error;
        }
        
        return METBaseResponseContract::newFromParameters(inventTransferId, result, message);
    }

    /// <summary>
    /// Create TO receipt parm header table
    /// </summary>
    /// <param name = "_header">TO receipt contract header</param>
    /// <param name = "_transferUpdateType">Type of TO udpate</param>
    /// <returns>TO receipt parm header table</returns>
    private InventTransferParmTable createInventTransferParmTable(METInventTransferOrderReceiveHeaderContract _header, InventTransferUpdateType _transferUpdateType)
    {
        InventTransferParmTable transferParmTable;

        transferParmTable.initParmDefault();
        transferParmTable.ParmId            = RunBaseMultiParm::getSysParmId();
        transferParmTable.UpdateType        = _transferUpdateType;
        transferParmTable.TransferId        = _header.parmInventTransferId();
        transferParmTable.ShipUpdateQty     = InventTransferShipUpdateQty::ShipNow;
        transferParmTable.ReceiveUpdateQty  = InventTransferReceiveUpdateQty::Shipment;
        transferParmTable.EditLines         = NoYes::Yes;

        transferParmTable.TransDate         = _header.parmPostingDate();
        transferParmTable.ExplodeLines      = NoYes::Yes;
        
        // false so lines are not automatically inserted as it's using obsolete API InventTransferParmLine\createShipLines
        transferParmTable.insert(false);

        return transferParmTable;
    }

/// <summary>
/// Create TO receipt parm lines table
/// </summary>
/// <param name = "_inventTransferParmTable">TO receipt parm header table</param>
private void createInventTransferParmLine(InventTransferParmTable _inventTransferParmTable)
{
    InventTransferParmLineCreate::newFromParameters(_inventTransferParmTable).createReceiveLines();
}

    /// <summary>
    /// Update TO receipt parm line table
    /// </summary>
    /// <param name = "_parmId">Parameter ID</param>
    /// <param name = "_lineContract">TO receipt line contract</param>
    /// <param name = "_inventTransferParmLineUpdatedTmp">TO receipt parm line temp table</param>
    private void updateInventTransferParmLine(ParmId _parmId, METInventTransferOrderReceiveLineContract _lineContract, InventTransferParmLine _inventTransferParmLineUpdatedTmp)
    {
        InventTransferParmLine  inventTransferParmLine;
        
        ttsbegin;
        select firstonly forupdate inventTransferParmLine
                             where inventTransferParmLine.ParmId == _parmId
                                && inventTransferParmLine.InventTransId == _lineContract.parmInventTransIdReceive();
                        
                        

        if (inventTransferParmLine)
        {
            inventTransferParmLine.QtyReceiveNow = _lineContract.parmInventTransferQtyReceived();
            inventTransferParmLine.PdsCWQtyReceiveNow = _lineContract.parmPdsCWQtyReceiveNow();
            inventTransferParmLine.update();

            // save the recod in a temp table to delete parm line records that were not in the line contract
            _inventTransferParmLineUpdatedTmp.data(inventTransferParmLine);
            _inventTransferParmLineUpdatedTmp.doInsert();
        }

        ttscommit;
    }

    /// <summary>
    /// Process TO receipt lines contract
    /// </summary>
    /// <param name = "_lines">List of TO receipt lines</param>
    /// <param name = "_parmId">Parameter ID</param>
    /// <param name = "_inventTransferId">Transfer order ID</param>
    /// <param name = "_inventTransferParmLineUpdatedTmp">TO receipt parm line temp table</param>
    /// <returns>Error message if any; otherwise, empty</returns>
    private Description255 processLinesContract(List _lines, ParmId _parmId, InventTransferId _inventTransferId, InventTransferParmLine _inventTransferParmLineUpdatedTmp)
    {
        METInventTransferOrderReceiveLineContract lineContract;        
        ListIterator listIterator;
        Description255 errorMessage;

        if (_lines)
        {
            listIterator = new ListIterator(_lines);

            _inventTransferParmLineUpdatedTmp.setTmp();

            while (listIterator.more())
            {
                lineContract = listIterator.value();

                // Validate line
                errorMessage = this.validateLine(lineContract, _inventTransferId);

                if (!errorMessage)
                {
                    // update InventTransferParmLine from line contract
                    this.updateInventTransferParmLine(_parmId, lineContract, _inventTransferParmLineUpdatedTmp);
                }
                else
                {
                    return errorMessage;
                }

                listIterator.next();
            }
        }
        else
        {
            errorMessage = "@MET:LinesValidation";
        }

        return errorMessage;
    }

/// <summary>
/// Post TO receipt after InventTransferParmTable created and inventTransferParmLine updated/deleted from contract
/// </summary>
/// <param name = "_inventTransferParmTable">TO receipt parm header table</param>
/// <param name = "_inventTransferParmLineUpdatedTmp">TO receipt parm line temp table</param>
private void postTOReceipt(InventTransferParmTable _inventTransferParmTable, InventTransferParmLine _inventTransferParmLineUpdatedTmp)
{
    InventTransferParmLine  inventTransferParmLine;
    
    // if at least one inventTransferParmLine was updated
    if (_inventTransferParmLineUpdatedTmp)
    {
        // delete inventTransferParmLine that were not received
        delete_from inventTransferParmLine
                          where inventTransferParmLine.ParmId == _inventTransferParmTable.ParmId
                    notexists join _inventTransferParmLineUpdatedTmp
                             where inventTransferParmLine.ParmId == _inventTransferParmLineUpdatedTmp.ParmId
                                && inventTransferParmLine.InventTransId == _inventTransferParmLineUpdatedTmp.InventTransId;
    
        InventTransferMultiReceive inventTransferMultiReceive = InventTransferMultiReceive::construct();
        inventTransferMultiReceive.runUpdate(_inventTransferParmTable);
    }
}

    /// <summary>
    /// Validate header contract
    /// </summary>
    /// <param name = "_headerContract">Header contract</param>
    /// <returns>Error message if any; otherwise, empty</returns>
    private Description255 validateHeaderDataAreaId(METInventTransferOrderReceiveHeaderContract _headerContract)
    {
        Description255 ret;

        InventTransferId transferId = _headerContract.parmInventTransferId();
        DataAreaId dataAreaId  = _headerContract.parmDataAreaId();

        // DataAreaId missing
        if (!dataAreaId)
        {
            return "@MET:DataAreaIdValidation";
        }

        DataArea dataArea;
        select firstonly dataArea where dataArea.Id == dataAreaId;

        // DataAreaId does not exist
        if (!dataArea)
        {
            return strFmt("@MET:DataAreaIdNotExist", dataAreaId);
 
        }

        return ret;
    }

    /// <summary>
    /// Validate header contract
    /// </summary>
    /// <param name = "_headerContract">Header contract</param>
    /// <returns>Error message if any; otherwise, empty</returns>
    private Description255 validateHeader(METInventTransferOrderReceiveHeaderContract _headerContract)
    {
        Description255 ret;

        InventTransferId transferId = _headerContract.parmInventTransferId();
        DataAreaId dataAreaId  = _headerContract.parmDataAreaId();

        InventTransferTable inventTransferTable = InventTransferTable::find(transferId);

        // TO does not exist
        if (!inventTransferTable)
        {
            return strFmt("@MET:TransferOrderNotExist", transferId, dataAreaId);
        }

        // TO fully received
        if (inventTransferTable.TransferStatus == InventTransferStatus::Received)
        {
            return strFmt("@MET:TransferOrderFullyReceived", transferId);
        }
        
        return ret;
    }

    /// <summary>
    /// Validate line contract
    /// </summary>
    /// <param name = "_lineContract">Line contract</param>
    /// <param name = "_inventTransferId">Transfer order ID</param>
    /// <returns>Error message if any; otherwise, empty</returns>
    private Description255 validateLine(METInventTransferOrderReceiveLineContract _lineContract, InventTransferId _inventTransferId)
    {
        Description255 ret;

        InventTransId inventTransIdReceive = _lineContract.parmInventTransIdReceive();
        InventTransferLine inventTransferLine = InventTransferLine::findTransIdReceive(inventTransIdReceive);

        // TO line does not exist
        if (!inventTransferLine)
        {
            return strFmt("@MET:TransferOrderLineNotExist", inventTransIdReceive);
        }

        // TO line belong to another TO
        if (inventTransferLine.TransferId != _inventTransferId)
        {
            return strFmt("@MET:TransferOrderLineDifferentTO", inventTransIdReceive, _inventTransferId);
        }

        // TO fully received
        if (inventTransferLine.RemainStatus == InventTransferRemainStatus::None)
        {
            return strFmt("@MET:TransferOrderLineFullyReceived", inventTransferLine.ItemId, inventTransIdReceive);
        }

        // TO not shipped
        if (inventTransferLine.QtyShipped == 0)
        {
            return strFmt("@MET:TransferOrderLineNotShipped", inventTransferLine.ItemId, inventTransIdReceive);
        }

        // TO receipt >= receive remain quantity
        if (_lineContract.parmInventTransferQtyReceived() > inventTransferLine.QtyRemainReceive)
        {
            return strFmt("@MET:TransferOrderLineOverReceived", inventTransferLine.ItemId, inventTransIdReceive, inventTransferLine.QtyRemainReceive);
        }

        return ret;
    }

    /// <summary>
    /// Validate receipts request
    /// </summary>
    /// <param name = "_countReceipt">Number of receipts in the request</param>
    /// <returns>Error message if any; otherwise, empty</returns>
    private Description255 validateReceipts(int _countReceipt)
    {
        int maxReceiptLimit = WHSParameters::find().METMaxTOReceipts;
        Description255 ret;

        if (_countReceipt > maxReceiptLimit)
        {
            return strFmt("@MET:RequestsValidation", _countReceipt, maxReceiptLimit);
        }

        return ret;
    }
